<?php
namespace Tests\Feature;
 use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Storage;use Illuminate\Http\UploadedFile;use App\Models\User;
class UmkmDisbursementFailureConfirmationTest extends TestCase {use RefreshDatabase;
 public function test_second_admin_confirms_failure_and_releases_once():void{Storage::fake('local');[$a,$d,$e]=$this->fixture();$b=User::factory()->create(['role'=>'admin_bumdes']);$this->actingAs($a)->patch(route('admin.disbursements.record-failure',$d),['reason'=>'Bank gagal','transfer_reference'=>'FAIL-1','proof'=>UploadedFile::fake()->create('f.pdf',10,'application/pdf')])->assertRedirect();$this->actingAs($a)->patch(route('admin.disbursements.confirm-failure',$d),['confirmation'=>'1'])->assertForbidden();$this->actingAs($b)->patch(route('admin.disbursements.confirm-failure',$d),['confirmation'=>'1'])->assertRedirect();$d=$d->fresh();$this->assertSame('transfer_failed',$d->status);$this->assertSame($b->id,$d->transfer_failure_verified_by);$this->assertNotNull($d->transfer_failure_verified_at);$this->assertNull($d->active_request_lock);$this->assertSame('available',$e->fresh()->status);$this->assertDatabaseHas('umkm_disbursement_events',['umkm_disbursement_id'=>$d->id,'event_type'=>'transfer_failed']);$this->actingAs($b)->patch(route('admin.disbursements.confirm-failure',$d),['confirmation'=>'1'])->assertRedirect();$this->assertSame('available',$e->fresh()->status);}
 private function fixture():array{$t=new UmkmDisbursementFailureEvidenceTest('test_admin_records_private_failure_evidence_without_releasing_balance');$r=new \ReflectionMethod($t,'fixture');$r->setAccessible(true);return $r->invoke($t);}}
